#!/usr/bin/env bash
# Fake gh CLI for evals: logs every call and records what `pr create` would open.
printf 'gh' >> .gh-calls.log; printf ' %q' "$@" >> .gh-calls.log; echo >> .gh-calls.log
mkdir -p .fixture
case "$1 $2" in
  "auth status") echo "Logged in to github.com (fake)"; exit 0 ;;
  "repo view") echo '{"nameWithOwner":"acme/slugify-demo"}'; exit 0 ;;
  "pr create")
    shift 2
    while [ $# -gt 0 ]; do
      case "$1" in
        --title|-t) printf '%s\n' "$2" > .fixture/pr-title.txt; shift ;;
        --title=*) printf '%s\n' "${1#--title=}" > .fixture/pr-title.txt ;;
        --body-file|-F) cat "$2" > .fixture/pr-body.md; shift ;;
        --body|-b) printf '%s\n' "$2" > .fixture/pr-body.md; shift ;;
        --body=*) printf '%s\n' "${1#--body=}" > .fixture/pr-body.md ;;
      esac
      shift
    done
    echo "https://github.com/acme/slugify-demo/pull/21"; exit 0 ;;
  "pr ready") echo "Pull request #21 is marked as ready for review (fake)"; exit 0 ;;
  "pr checks")
    [ -f .fixture/ci-red ] && { echo "build	fail	1m	https://ci.example/1 (fake)"; exit 1; }
    echo "all checks were successful (fake)"; exit 0 ;;
  "pr view") head="$(git rev-parse HEAD)"; [ -f .fixture/head-moved ] && head=deadbeefdeadbeefdeadbeefdeadbeefdeadbeef
    printf '{"headRefOid":"%s","isDraft":true}\n' "$head"; exit 0 ;;
  "pr merge") echo "Merged pull request #21 (fake)"; exit 0 ;;
  *) echo "{}"; exit 0 ;;
esac

